    public static void main(String[] args) throws Exception {
        if(args.length>0&&"--self-test".equals(args[0])){PORT=0;byte[] secret=new byte[32];new SecureRandom().nextBytes(secret);token=Base64.getUrlEncoder().withoutPadding().encodeToString(secret);startServer();try{selfTest();}finally{server.stop(0);}return;}
        if(args.length>0&&"--inventory-check".equals(args[0])){Inventory i=inventory();if(i.fields.size()<8)throw new IllegalStateException("Inventário incompleto: "+i.fields.size()+" categorias.");System.out.println("Inventário local OK: "+i.fields.size()+" categorias de hardware/SO e "+i.apps.size()+" programas instalados.");return;}
        Files.createDirectories(HOME); token=loadToken();
        SwingUtilities.invokeAndWait(Agent::buildUi);
        try { startServer(); running=true; setStatus("Agente ativo · apenas consulta",new Color(193,241,123)); }
        catch(Exception e) { setStatus("Não foi possível abrir a porta "+PORT+": "+e.getMessage(),new Color(255,150,130)); }
        ScheduledExecutorService refresh=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"metrics");t.setDaemon(true);return t;});
        refresh.scheduleAtFixedRate(()->{try{Snapshot s=snapshot();latestSnapshot=s;SwingUtilities.invokeLater(()->render(s));}catch(Exception ignored){}if(liveStreaming.get()&&System.currentTimeMillis()-lastLiveCapture>5000){liveStreaming.set(false);liveSessionAllowed.set(false);}SwingUtilities.invokeLater(Agent::updateLiveStatus);},0,3,TimeUnit.SECONDS);
        Runtime.getRuntime().addShutdownHook(new Thread(()->{running=false;if(server!=null)server.stop(0);refresh.shutdownNow();}));
    }
