    private static boolean brandedConfirm(String title,String message,String acceptText,String cancelText){final boolean[] accepted={false};JDialog dialog=new JDialog(frame,title,Dialog.ModalityType.APPLICATION_MODAL);dialog.setUndecorated(true);dialog.setDefaultCloseOperation(WindowConstants.DO_NOTHING_ON_CLOSE);JPanel shell=new JPanel(new BorderLayout());shell.setBackground(BG);shell.setBorder(BorderFactory.createLineBorder(LINE));dialog.setContentPane(shell);JPanel top=new JPanel(new BorderLayout());top.setBackground(new Color(9,12,18));top.setBorder(new EmptyBorder(5,12,5,7));top.setPreferredSize(new Dimension(500,40));JPanel brand=new JPanel(new FlowLayout(FlowLayout.LEFT,9,0));brand.setOpaque(false);brand.add(new JLabel(vectorIcon(3,GREEN,17)));JLabel heading=label(title,TEXT,12);heading.setFont(new Font("Segoe UI",Font.BOLD,12));brand.add(heading);top.add(brand,BorderLayout.WEST);JButton close=windowButton(6);close.addActionListener(e->dialog.dispose());top.add(close,BorderLayout.EAST);java.awt.event.MouseAdapter drag=new java.awt.event.MouseAdapter(){public void mouseDragged(java.awt.event.MouseEvent e){Point p=e.getLocationOnScreen();dialog.setLocation(p.x-e.getX(),p.y-e.getY());}};top.addMouseListener(drag);top.addMouseMotionListener(drag);shell.add(top,BorderLayout.NORTH);JPanel body=new JPanel(new BorderLayout(15,0));body.setBackground(BG);body.setBorder(new EmptyBorder(25,25,22,25));body.add(new JLabel(vectorIcon(3,GREEN,24)),BorderLayout.WEST);JTextArea copy=new JTextArea(message);copy.setEditable(false);copy.setFocusable(false);copy.setLineWrap(true);copy.setWrapStyleWord(true);copy.setFont(new Font("Segoe UI",Font.PLAIN,14));copy.setForeground(new Color(220,227,234));copy.setBackground(BG);copy.setBorder(null);int wrappedLines=Math.max(2,(message.length()+57)/58);copy.setPreferredSize(new Dimension(405,Math.max(84,Math.min(190,wrappedLines*23))));body.add(copy,BorderLayout.CENTER);shell.add(body,BorderLayout.CENTER);JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT,10,0));actions.setBackground(BG);actions.setBorder(new EmptyBorder(0,20,20,20));if(cancelText!=null&&!cancelText.isBlank()){JButton cancel=secondaryButton(cancelText);cancel.addActionListener(e->dialog.dispose());actions.add(cancel);dialog.getRootPane().setDefaultButton(cancel);dialog.getRootPane().registerKeyboardAction(e->dialog.dispose(),KeyStroke.getKeyStroke("ESCAPE"),JComponent.WHEN_IN_FOCUSED_WINDOW);}JButton accept=button(acceptText);accept.addActionListener(e->{accepted[0]=true;dialog.dispose();});actions.add(accept);if(cancelText==null||cancelText.isBlank())dialog.getRootPane().setDefaultButton(accept);shell.add(actions,BorderLayout.SOUTH);dialog.addWindowListener(new java.awt.event.WindowAdapter(){public void windowClosing(java.awt.event.WindowEvent e){dialog.dispose();}});dialog.setResizable(false);dialog.pack();dialog.setSize(Math.max(460,Math.min(560,dialog.getWidth())),dialog.getHeight());dialog.setLocationRelativeTo(frame);dialog.setAlwaysOnTop(true);dialog.setVisible(true);return accepted[0];}
