    private static Icon vectorIcon(int kind,Color color,int size){return new Icon(){public int getIconWidth(){return size;}public int getIconHeight(){return size;}public void paintIcon(Component c,Graphics graphics,int x,int y){Graphics2D g=(Graphics2D)graphics.create();g.translate(x,y);g.setColor(color);g.setStroke(new BasicStroke(Math.max(1.4f,size/11f),BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);int s=size;switch(kind){case 0:g.drawRoundRect(2,2,s/2-3,s/2-3,3,3);g.drawRoundRect(s/2+1,2,s/2-3,s/2-3,3,3);g.drawRoundRect(2,s/2+1,s/2-3,s/2-3,3,3);g.drawRoundRect(s/2+1,s/2+1,s/2-3,s/2-3,3,3);break;case 1:g.drawRoundRect(s/4,s/4,s/2,s/2,3,3);for(int i=0;i<3;i++){int p=s/3+i*s/6;g.drawLine(p,1,p,s/4);g.drawLine(p,3*s/4,p,s-1);g.drawLine(1,p,s/4,p);g.drawLine(3*s/4,p,s-1,p);}break;case 2:g.drawRoundRect(3,2,s-6,s-4,3,3);g.drawLine(6,s/3,s-6,s/3);g.drawLine(6,s/2,s-6,s/2);g.drawLine(6,2*s/3,s-8,2*s/3);break;case 3:Polygon shield=new Polygon(new int[]{s/2, s-3, s-4, s/2, 4, 3},new int[]{2,5,s/2,s-2,s/2,5},6);g.drawPolygon(shield);g.drawLine(s/3,s/2,s/2-1,2*s/3);g.drawLine(s/2-1,2*s/3,2*s/3,s/3);break;case 4:g.drawLine(3,s/2,s-3,s/2);break;case 5:g.drawRect(3,3,s-6,s-6);break;case 6:g.drawLine(4,4,s-4,s-4);g.drawLine(s-4,4,4,s-4);break;}g.dispose();}};}
    private static boolean installTray(BufferedImage logo){if(!SystemTray.isSupported()||logo==null)return false;try{systemTray=SystemTray.getSystemTray();PopupMenu menu=new PopupMenu();MenuItem open=new MenuItem("Abrir MarlicoBot PC");open.addActionListener(e->showFromTray());MenuItem state=new MenuItem("Monitor ativo · consulta somente leitura");state.setEnabled(false);MenuItem quit=new MenuItem("Sair e parar o monitoramento");quit.addActionListener(e->exitAgent());menu.add(open);menu.add(state);menu.addSeparator();menu.add(quit);Image image=logo.getScaledInstance(32,32,Image.SCALE_SMOOTH);trayIcon=new TrayIcon(image,"MarlicoBot PC · monitor ativo",menu);trayIcon.setImageAutoSize(true);trayIcon.addActionListener(e->showFromTray());systemTray.add(trayIcon);return true;}catch(Exception e){systemTray=null;trayIcon=null;return false;}}
    private static void showFromTray(){SwingUtilities.invokeLater(()->{if(frame==null)return;frame.setVisible(true);frame.setExtendedState(Frame.NORMAL);frame.toFront();frame.requestFocus();});}
    private static void hideToTray(){if(trayIcon!=null){frame.setVisible(false);trayIcon.displayMessage("MarlicoBot PC","O monitor continua ativo em segundo plano.",TrayIcon.MessageType.INFO);}else frame.setState(Frame.ICONIFIED);}
    private static void exitAgent(){if(!brandedConfirm("Sair do MarlicoBot PC","Parar o monitoramento e desconectar este computador do app e do Telegram? O agente voltará a iniciar na próxima entrada no Windows.","Sair e parar","Continuar usando"))return;running=false;if(server!=null)server.stop(0);if(systemTray!=null&&trayIcon!=null)systemTray.remove(trayIcon);frame.dispose();System.exit(0);}
