    private static void loadInventory(){if(inventoryState==null||!inventoryPending.compareAndSet(false,true))return;inventoryState.setText("Lendo hardware e lista de aplicativos…");Thread t=new Thread(()->{try{Inventory i=inventory();latestInventory=i;SwingUtilities.invokeLater(()->renderInventory(i));}catch(Exception e){SwingUtilities.invokeLater(()->inventoryState.setText("Não foi possível ler o inventário. Tente novamente."));}finally{inventoryPending.set(false);}},"system-inventory");t.setDaemon(true);t.start();}
    private static void renderInventory(Inventory i){if(inventoryState==null)return;inventoryCards.removeAll();for(Map.Entry<String,String> pair:i.fields.entrySet()){JPanel p=card();p.setLayout(new BorderLayout(0,7));p.add(label(pair.getKey().toUpperCase(Locale.ROOT),MUTED,10),BorderLayout.NORTH);p.add(label(pair.getValue().isEmpty()?"Não informado":pair.getValue(),TEXT,14),BorderLayout.CENTER);inventoryCards.add(p);}inventoryCards.revalidate();inventoryCards.repaint();softwareModel.clear();for(String[] app:i.apps)softwareModel.addElement(app);inventoryState.setText("Atualizado em "+new java.text.SimpleDateFormat("dd/MM/yyyy HH:mm:ss").format(new Date())+"  ·  "+i.apps.size()+" aplicativos encontrados");}
